    if (select(STDIN_FILENO + 1, &readfds, NULL, NULL, &tv) > 0) {
        char buf[1];
        if (read(STDIN_FILENO, buf, 1) > 0) {
            return buf[0];
        }
    }
    return 0;
}

static void handle_key(char key) {
    if (key == 'q') {
        exit(0);
    } else if (key == 'a') {
        async_scroll = !async_scroll;
    } else if (key == 'b') {
        bold = !bold;
    } else if (key == 'B') {
        all_bold = 1;
        bold = 1;
    } else if (key == 'n') {
        no_bold = 1;
        bold = 0;
    } else if (isdigit(key)) {
        update_delay = key - '0';
    } else if (key == '!') {
        color = "red";
    } else if (key == '@') {
        color = "green";
    } else if (key == '#') {
        color = "yellow";
    } else if (key == '$') {
        color = "blue";
    } else if (key == '%') {
        color = "magenta";
    } else if (key == '^') {
        color = "cyan";
    } else if (key == '&') {
        color = "white";
    } else if (key == ')') {
        color = "black";
    }
}

static void print_matrix(void) {
    // Clear screen
    printf(CSI "2J");

    // Print message if set
    if (message) {
        int mid_row = rows / 2;
        printf(CSI "%d;1H", mid_row);
        printf(BOLD "%s", message);
        printf(RESET);
    }

    // Print matrix
    for (int col = 0; col < cols; col++) {
        for (int row = 0; row < rows; row++) {
            char ch = get_char();
            int col_idx = (col * rows + row) % (rows * cols);
            int color_idx = get_color_index();
            int bold_flag = get_bold_setting();

            printf(CSI "%dm", color_idx);
            if (bold_flag) {
                printf(BOLD);
            }
            printf("%c", ch);
            printf(RESET);
        }
    }

    // Move cursor to bottom left
    printf(CSI "%d;1H", rows);
}

int main(int argc, char *argv[]) {
    parse_args(argc, argv);

    init_terminal();

    // Main loop
    while (1) {
        print_matrix();

        // Sleep based on delay
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = update_delay * 100000000L;
        nanosleep(&ts, NULL);

        // Check for keystrokes
        if (!screensaver) {
            char key = get_key();
            if (key) {
                handle_key(key);
            }
        }
    }

    restore_terminal();
    return 0;
}
